const builtins=raw.map(([en,vi,type],i)=>({id:`builtin-${i}`,en,vi,type,sourceLanguageCode:'en',targetLanguageCode:'vi'}));
const $=s=>document.querySelector(s), modal=$('#modal'), content=$('#modal-content');
let storageOK=true;function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))||fallback}catch{storageOK=false;return fallback}}let personal=read('golocal.phrases',[]),hotel=read('golocal.hotel',{}),active=null,scrollY=0,toastTimer;
if(!Array.isArray(personal))personal=[];
function save(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{storageOK=false;toast('Browser storage is unavailable. Changes cannot be saved.');return false}}
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4500)}
function el(tag,cls,text){const e=document.createElement(tag);if(cls)e.className=cls;if(text!==undefined)e.textContent=text;return e}
function stopAudio(){window.speechSynthesis?.cancel()}
function open(){if(!modal.open){scrollY=window.scrollY;modal.showModal();document.body.style.overflow='hidden'}}function close(){stopAudio();modal.close();document.body.style.overflow='';window.scrollTo(0,scrollY)}modal.addEventListener('cancel',e=>{e.preventDefault();close()});$('#close').onclick=close;$('#back').onclick=close;
$('#settings').innerHTML=icon('settings');$('#search-icon').innerHTML=icon('search');$('#listen-home').textContent='Listen to Vietnamese';$('#search-toggle').innerHTML=icon('search');$('.say-mic').innerHTML=icon('mic');$('#listen-home').onclick=()=>listen();$('#settings').onclick=settings;$('#hotel').onclick=hotelForm;$('#add').onclick=()=>composer();
function render(){const list=$('#phrase-list');list.replaceChildren();const q=$('#search').value.toLocaleLowerCase().trim();const groups=[['YOUR PHRASES',personal],['',builtins]];let total=0;for(const [label,items]of groups){const matches=items.filter(p=>p.en.toLocaleLowerCase().includes(q));total+=matches.length;if(!matches.length)continue;if(label)list.append(el('div','group-label',label));for(const p of matches){const row=el('div','phrase-row'),button=el('button','phrase');button.append(el('span','phrase-text',p.en));button.onclick=()=>showPhrase(p);row.append(button);if(!p.id.startsWith('builtin')){const menu=el('button','edit-btn','⋯');menu.setAttribute('aria-label',`Edit ${p.en}`);menu.onclick=()=>composer(p);row.append(menu)}list.append(row)}}if(!total){const empty=el('div','empty','No phrases found. Tap “Say something” to write your own.');const add=el('button','primary full','Say something');add.onclick=()=>composer(null,$('#search').value);empty.append(add);list.append(empty)}$('#hotel-summary').textContent=hotel.address?(hotel.name||hotel.address):'Add your stay details for an easy ride back'}
function toggleSearch(show){$('#phrase-search').hidden=!show;$('#search-toggle').setAttribute('aria-expanded',String(show));$('#search-toggle').setAttribute('aria-label',show?'Close search':'Search phrases');if(show){$('#search').focus()}else{$('#search').value='';render();$('#search-toggle').focus()}}$('#search-toggle').onclick=()=>toggleSearch($('#phrase-search').hidden);$('#search').oninput=render;$('#search').onkeydown=e=>{if(e.key==='Escape'){e.preventDefault();toggleSearch(false)}};document.addEventListener('keydown',e=>{if(e.key==='/'&&!modal.open&&!['INPUT','TEXTAREA'].includes(document.activeElement.tagName)){e.preventDefault();toggleSearch(true)}});
function audioButton(text){const b=el('button','icon-btn');b.innerHTML=icon('speaker');b.setAttribute('aria-label','Speak Vietnamese');b.onclick=()=>{stopAudio();if(!window.speechSynthesis){toast('Audio playback is unavailable in this browser.');return}const voice=speechSynthesis.getVoices().find(v=>v.lang.toLowerCase().startsWith('vi'));if(!voice){toast('No Vietnamese voice is available in this browser. You can still show the text.');return}const utterance=new SpeechSynthesisUtterance(text);utterance.voice=voice;utterance.lang=destination.speechLocale;utterance.rate=.85;utterance.onstart=()=>{b.textContent='■';b.setAttribute('aria-label','Stop playback');b.onclick=()=>{stopAudio();reset()}};const reset=()=>{b.replaceWith(audioButton(text))};utterance.onend=reset;utterance.onerror=()=>{reset();toast('Audio could not play. Please try again.')};speechSynthesis.speak(utterance)};return b}
function showPhrase(p){stopAudio();active=p;content.replaceChildren();const top=el('div','translation-top');top.append(el('span','label','SHOW THIS · VIETNAMESE'),audioButton(p.vi));const translation=el('div','translation',p.vi);translation.lang='vi';content.append(top,translation,el('p','original',p.en));if(p.id==='builtin-0'){if(hotel.address){const block=el('div','address');block.append(el('strong','',hotel.name||'Your destination'),document.createTextNode(hotel.address));content.append(block)}else{const b=el('button','secondary full','＋ Add your hotel address');b.onclick=()=>hotelForm(()=>showPhrase(p));content.append(b)}}const listenButton=el('button','primary full');listenButton.innerHTML=icon('mic')+' Listen to their reply';listenButton.onclick=()=>listen(p);content.append(listenButton,el('div','notice','Hold your screen up so the other person can read it. Tap the speaker to play it aloud when a Vietnamese voice is available.'));open()}
function listen(p){stopAudio();if(p)showPhrase(p);else{content.replaceChildren(el('h2','','Listen to Vietnamese'));open()}const existing=$('#listen-notice');existing?.remove();const notice=el('div','notice','Spoken reply translation is not connected yet. No recording has started. Saved Vietnamese phrases are ready to show; live replies need a configured speech and translation service.');notice.id='listen-notice';content.append(notice);notice.scrollIntoView({block:'nearest'})}
function hotelForm(onSave){stopAudio();content.innerHTML='<h2>Your home away from home</h2><p class="notice">Keep the exact name and address, including Vietnamese accents. Show these to your driver.</p><form id="hotel-form"><label class="form-label" for="hotel-name">Hotel name</label><input class="field" id="hotel-name" maxlength="200" autocomplete="organization" placeholder="Where are you staying?"><label class="form-label" for="hotel-address">Exact address</label><textarea class="field" id="hotel-address" maxlength="1000" required placeholder="Paste your hotel’s full address"></textarea><button class="primary full" type="submit">Save hotel address</button><button class="text-btn danger full" id="clear-hotel" type="button">Clear saved address</button></form>';$('#hotel-name').value=hotel.name||'';$('#hotel-address').value=hotel.address||'';$('#hotel-form').onsubmit=e=>{e.preventDefault();const address=$('#hotel-address').value;if(!address.trim()){$('#hotel-address').setCustomValidity('Enter your hotel address.');$('#hotel-address').reportValidity();return}const next={name:$('#hotel-name').value,address,countryCode:destination.countryCode};if(save('golocal.hotel',next)){hotel=next;render();onSave?onSave():close();toast('Hotel address saved')}};$('#hotel-address').oninput=()=>$('#hotel-address').setCustomValidity('');$('#clear-hotel').onclick=()=>{if(save('golocal.hotel',{})){hotel={};render();close();toast('Hotel address cleared')}};open()}
function composer(edit=null,initial=''){stopAudio();content.innerHTML='<h2></h2><label class="form-label" for="phrase-input">YOUR PHRASE · ENGLISH</label><textarea id="phrase-input" class="field" maxlength="500" placeholder="What would you like to say?"></textarea><div class="counter"></div><div class="actions"><button class="secondary" id="dictate" aria-label="Dictate English"></button><button class="primary" id="translate">Translate to Vietnamese</button></div><div id="translation-result" aria-live="polite"></div>';content.querySelector('h2').textContent=edit?'Edit your phrase':'Make it your own';const input=$('#phrase-input');input.value=edit?.en||initial;$('#dictate').innerHTML=icon('mic');$('#dictate').onclick=()=>toast('English dictation is not connected. You can type your phrase.');const sync=()=>{$('.counter').textContent=`${input.value.length} / 500`;$('#translate').disabled=!input.value.trim();$('#translation-result').replaceChildren()};input.oninput=sync;sync();$('#translate').onclick=()=>{const en=input.value.trim();const match=builtins.find(p=>p.en.toLowerCase().replace(/[.!?]$/,'')===en.toLowerCase().replace(/[.!?]$/,''));const result=$('#translation-result');result.replaceChildren();if(!match){result.append(el('div','notice','New translations are not connected yet. Your text is kept here so you can revise it. You can use any of the prepared phrases now.'));return}const translation=el('div','translation',match.vi);translation.lang='vi';result.append(el('div','notice','This matches a prepared phrase.'),translation,audioButton(match.vi));const button=el('button','primary full',edit?'Save changes':'Save phrase');button.onclick=()=>{const now=new Date().toISOString();const p={id:edit?.id||crypto.randomUUID(),en,vi:match.vi,type:match.type,sourceLanguageCode:'en',targetLanguageCode:destination.languageCode,createdAt:edit?.createdAt||now,updatedAt:now};const next=edit?personal.map(x=>x.id===edit.id?p:x):[p,...personal];if(save('golocal.phrases',next)){personal=next;render();showPhrase(p);toast('Phrase saved')}};result.append(button)};if(edit){const remove=el('button','text-btn danger full','Delete this phrase');remove.onclick=()=>{const next=personal.filter(p=>p.id!==edit.id);if(save('golocal.phrases',next)){personal=next;render();close();toast('Phrase deleted')}};content.append(remove)}open()}
function settings(){content.innerHTML='<h2>Your travel companion</h2><div class="notice"><strong>🇻🇳 Vietnam · Vietnamese</strong><br>More destinations can be added in a future release.</div><button class="secondary full" id="settings-hotel">Edit hotel address</button><div class="notice"><strong>Available now</strong><br>Prepared translations, search, hotel details and saving prepared phrases. Text is stored in this browser. Browser playback needs an available Vietnamese voice.</div><div class="notice"><strong>Live translation & speech</strong><br>Not connected yet. Microphone recording is disabled. When connected, audio will be sent to a service for transcription and translation only after you tap record.</div><div class="notice" id="offline-status"></div><div class="notice">Starter translations need native-speaker review before broader release.</div>';$('#offline-status').textContent=navigator.serviceWorker?.controller?'Offline text caching is active in this browser. Saved data may still be cleared by browser settings.':'Offline text preparation requires a successful online load and service-worker support. Reload after your first visit to activate it.';$('#settings-hotel').onclick=()=>hotelForm();open()}
window.addEventListener('pagehide',stopAudio);document.addEventListener('visibilitychange',()=>{if(document.hidden)stopAudio()});window.addEventListener('offline',()=>toast('You are offline. Prepared phrases are still available.'));render();if(!storageOK)toast('Browser storage is unavailable. Personal changes cannot persist.');if('speechSynthesis'in window)speechSynthesis.getVoices();if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>toast('Offline preparation is unavailable in this browser.'));
